static inline float isolation_forest_decision_function(const float *features) {
    return isolation_forest_score_samples(features) - -0.70847559f;
}

// Predict: 1 for normal (inlier), -1 for anomaly (outlier)
static inline int isolation_forest_predict(const float *features) {
    return isolation_forest_decision_function(features) >= 0.0f ? 1 : -1;
}

// Compatibility aliases
static inline float anomaly_model_score_samples(const float *features) {
    return isolation_forest_score_samples(features);
}

static inline float anomaly_model_decision_function(const float *features) {
    return isolation_forest_decision_function(features);
}

